def copy_site_media_forward(apps, schema_editor):
    """Move uploaded hero/intro photos and the three social links into their new tables."""
    SiteSettings = apps.get_model('Tour_travels', 'SiteSettings')
    BackgroundImage = apps.get_model('Tour_travels', 'BackgroundImage')
    SocialLink = apps.get_model('Tour_travels', 'SocialLink')
    site = SiteSettings.objects.filter(pk=1).first()
    if site is None:
        return
    for section, field in [('hero', 'hero_image'), ('intro', 'intro_image')]:
        image = getattr(site, field)
        if image:
            BackgroundImage.objects.update_or_create(section=section, defaults={'image': image.name})
    order = 0
    for platform, field in [('facebook', 'facebook_url'), ('instagram', 'instagram_url'), ('x', 'x_url')]:
        url = getattr(site, field)
        if url:
            SocialLink.objects.create(platform=platform, url=url, order=order, is_active=True)
            order += 1


